const num = (v, name, min, max) => { const n = Number(v); if (!Number.isFinite(n) || n < min || n > max) throw new Error(name + ' must be between ' + min + ' and ' + max + '.'); return n; };
const bool = (v) => !(v === false || v === 'false');
const idOf = (v) => { if (v === null || v === undefined || v === '') return null; const n = parseInt(v, 10); if (!Number.isInteger(n) || n < 1) throw new Error('Invalid id.'); return n; };
const b = $('Webhook: save-package').first().json.body || {};
const name = clean(b.name, 80); if (!name) throw new Error('Give the package a name.');
return [{ json: { id: idOf(b.id), name, sessions: Math.round(num(b.sessions, 'Sessions', 1, 500)), price: Math.round(num(b.price, 'Price', 0, 100000000) * 100) / 100, validDays: Math.round(num(b.valid_days, 'Valid days', 1, 3650)), productId: idOf(b.product_id), isActive: bool(b.is_active) } }];

