WITH upd AS (UPDATE packages SET name = $2, sessions = $3::int, price = $4::numeric, valid_days = $5::int, product_id = $6::int, is_active = $7::boolean WHERE id = $1::int RETURNING id),
ins AS (INSERT INTO packages (name, sessions, price, valid_days, product_id, is_active) SELECT $2, $3::int, $4::numeric, $5::int, $6::int, $7::boolean WHERE $1::int IS NULL RETURNING id)
SELECT id FROM upd UNION ALL SELECT id FROM ins;

