WITH p AS (UPDATE client_packages SET status = 'cancelled' WHERE $2 = 'package' AND id = $1::int RETURNING id),
m AS (UPDATE client_memberships SET status = 'cancelled' WHERE $2 = 'membership' AND id = $1::int RETURNING id)
